package com.johnny.hotel.settlement;import lombok.*;import jakarta.validation.*;import jakarta.validation.constraints.*;import java.math.*;import java.time.*;import java.util.*;
public final class SettlementRequests{private SettlementRequests(){}
 @Data@Builder@NoArgsConstructor@AllArgsConstructor public static class Item{@NotBlank@Size(max=30)String sourceType;@NotNull Long sourceId;@NotBlank@Size(max=100)String providerPaymentId;@NotBlank@Pattern(regexp="IN|OUT")String direction;@NotNull@DecimalMin("0.01")@Digits(integer=10,fraction=2)BigDecimal grossAmount;@NotNull@DecimalMin("0.00")@Digits(integer=10,fraction=2)BigDecimal feeAmount;@NotNull@DecimalMin("0.00")@Digits(integer=10,fraction=2)BigDecimal netAmount;@NotBlank@Pattern(regexp="[A-Z]{3}")String currency;LocalDateTime providerOccurredAt;}
 @Data@Builder@NoArgsConstructor@AllArgsConstructor public static class Import{@NotBlank@Size(max=30)String provider;@NotBlank@Size(max=100)String providerBatchId;@NotBlank@Pattern(regexp="[A-Z]{3}")String currency;LocalDateTime periodStart,periodEnd,providerCreatedAt,providerSettledAt;@NotNull@DecimalMin("0.01")@Digits(integer=10,fraction=2)BigDecimal grossAmount;@NotNull@DecimalMin("0.00")@Digits(integer=10,fraction=2)BigDecimal feeAmount;@NotNull@DecimalMin("0.00")@Digits(integer=10,fraction=2)BigDecimal netAmount;@NotEmpty@Valid List<Item> items;}
 @Data@Builder@NoArgsConstructor@AllArgsConstructor public static class Payout{@NotBlank@Size(max=100)String providerPayoutId;@NotNull@DecimalMin("0.01")@Digits(integer=10,fraction=2)BigDecimal amount;@NotBlank@Pattern(regexp="[A-Z]{3}")String currency;LocalDateTime expectedAt;@NotNull LocalDateTime paidAt;@Size(max=100)String bankReference;}
 @Data@Builder@NoArgsConstructor@AllArgsConstructor public static class Reconcile{@NotBlank@Size(max=100)String requestKey;}
}
